import { writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

const target = fileURLToPath(new URL('../cordis.patch.yml', import.meta.url))
const content = [
  '# Generated by scripts/generate-package-assets.mjs.',
  '# The desktop workbench must be installed first because it owns opaque file refs.',
  '- insert:',
  '    - id: dsh-semantic-file-editor',
  "      name: '@yeisme/dsh-semantic-file-editor'",
  '',
].join('\n')

await writeFile(target, content, 'utf8')
